-- game_categories.lua -- which shelf each plugin of this fleet sits on.
--
-- GENERATED by .github/scripts/update_manifest.py from
-- .github/scripts/categories.json -- edit that file, not this one. Read by
-- games_menu.lua (Tools > Games) and by Dashboard, so the device groups games
-- the same way PluginManager's catalogue does.
--
-- Labels are English and go through _() at the call site (French in i18n.lua).
-- A plugin missing from BY_ID (newer than this copy of game-common) lands in
-- "other", which always sorts last. Pure data: no KOReader dependency.

local Categories = {}

-- Display order. "other" is the shelf of unknown plugins.
Categories.ORDER = {
    "logic",
    "sudoku",
    "words",
    "board",
    "cards",
    "classic",
    "party",
    "tools",
    "other",
}

-- English labels (translated by the caller).
Categories.LABELS = {
    logic   = "Logic puzzles",
    sudoku  = "Sudoku",
    words   = "Word games",
    board   = "Board games",
    cards   = "Card & dice games",
    classic = "Classic puzzles",
    party   = "Party & quiz",
    tools   = "Utilities",
    other   = "Other",
}

